import { z } from "zod"

// Shared by the browser and the server: the shape of a Rule, its validation,
// and its Rule Description. Nothing here may read private data.

export type PriceDirection = "above" | "below"
export type PercentDirection = "rises" | "falls"

/** A Rule as the Owner writes it in the form. */
export type RuleInput =
  | {
      kind: "price"
      direction: PriceDirection
      threshold: { source: "typed"; price: string } | { source: "price_paid" }
    }
  | { kind: "percentage"; direction: PercentDirection; percent: string }

/** A Rule with its threshold resolved; Price Paid is already a number. */
export type Rule =
  | {
      kind: "price"
      direction: PriceDirection
      source: "typed" | "price_paid"
      threshold: string
    }
  | { kind: "percentage"; direction: PercentDirection; percent: string }

export interface AlertInput {
  symbol: string
  title: string
  rule: RuleInput
}

/** Field errors keyed by dotted path: "symbol", "title", "rule.threshold.price", "rule.threshold", "rule.percent". */
export type AlertFieldErrors = Record<string, string>

export const TITLE_MAX_LENGTH = 80

const ruleInputSchema = z.discriminatedUnion("kind", [
  z.object({
    kind: z.literal("price"),
    direction: z.enum(["above", "below"]),
    threshold: z.discriminatedUnion("source", [
      z.object({ source: z.literal("typed"), price: z.string() }),
      z.object({ source: z.literal("price_paid") }),
    ]),
  }),
  z.object({
    kind: z.literal("percentage"),
    direction: z.enum(["rises", "falls"]),
    percent: z.string(),
  }),
])

/** The structural shape only: what a server function accepts over the wire. */
export const alertInputSchema = z.object({
  symbol: z.string(),
  title: z.string(),
  rule: ruleInputSchema,
})

/**
 * The full Rule schema for one Instrument: the shape plus every limit that
 * depends on it. Used by the form for feedback and by the server as the authority.
 */
export function alertSchemaFor(decimals: number): z.ZodType<AlertInput> {
  return alertInputSchema.superRefine((input, context) => {
    const report = (path: string[], message: string | null) => {
      if (message) {
        context.addIssue({ code: "custom", path, message })
      }
    }
    if ([...input.title.trim()].length > TITLE_MAX_LENGTH) {
      report(
        ["title"],
        `Keep the title to ${TITLE_MAX_LENGTH} characters or fewer`
      )
    }
    const { rule } = input
    if (rule.kind === "price" && rule.threshold.source === "typed") {
      report(
        ["rule", "threshold", "price"],
        priceProblem(rule.threshold.price.trim(), decimals)
      )
    }
    if (rule.kind === "percentage") {
      report(
        ["rule", "percent"],
        percentProblem(rule.percent.trim(), rule.direction)
      )
    }
  })
}

const PLAIN_DECIMAL = /^\d+(\.\d+)?$/
const PERCENT_DECIMALS = 2

function fractionDigits(value: string): number {
  return normaliseDecimal(value).split(".")[1]?.length ?? 0
}

function priceProblem(price: string, decimals: number): string | null {
  if (!price) {
    return "Enter a price"
  }
  if (!PLAIN_DECIMAL.test(price)) {
    return "Enter a price as a number, like 300.50"
  }
  if (normaliseDecimal(price) === "0") {
    return "Enter a price above 0"
  }
  if (fractionDigits(price) > decimals) {
    return decimals === 0
      ? "This instrument is priced in whole numbers"
      : `This instrument is priced to ${decimals} decimal places`
  }
  return null
}

function percentProblem(
  percent: string,
  direction: PercentDirection
): string | null {
  if (!percent) {
    return "Enter a percentage"
  }
  if (!PLAIN_DECIMAL.test(percent)) {
    return "Enter a percentage as a number, like 5 or 2.5"
  }
  if (fractionDigits(percent) > PERCENT_DECIMALS) {
    return `Use at most ${PERCENT_DECIMALS} decimal places`
  }
  const value = Number(percent)
  if (value === 0) {
    return "Enter a percentage above 0"
  }
  if (direction === "falls" && value >= 100) {
    return "A fall must be less than 100%"
  }
  if (direction === "rises" && value > 1000) {
    return "A rise can be at most 1000%"
  }
  return null
}

export function toFieldErrors(error: z.ZodError): AlertFieldErrors {
  const fieldErrors: AlertFieldErrors = {}
  for (const issue of error.issues) {
    const path = issue.path.join(".")
    fieldErrors[path] ??= issue.message
  }
  return fieldErrors
}

/** A float (as the Holdings service stores Price Paid) as a plain decimal string: 6.12e-6 → "0.00000612". */
const fromFloat = new Intl.NumberFormat("en-US", {
  useGrouping: false,
  maximumSignificantDigits: 15,
})

export function decimalFromNumber(value: number): string {
  return fromFloat.format(value)
}

/** "5.00" → "5", "0070.50" → "70.5". Input must be a plain decimal string. */
export function normaliseDecimal(value: string): string {
  const [whole, fraction = ""] = value.trim().split(".")
  const normalisedWhole = whole.replace(/^0+(?=\d)/, "")
  const normalisedFraction = fraction.replace(/0+$/, "")
  return normalisedFraction
    ? `${normalisedWhole}.${normalisedFraction}`
    : normalisedWhole
}

/** Pads or keeps a decimal string to the Instrument's decimals: ("291.4", 2) → "291.40". */
export function formatDecimal(value: string, decimals: number): string {
  const [whole, fraction = ""] = normaliseDecimal(value).split(".")
  const padded = fraction.padEnd(decimals, "0")
  return padded ? `${whole}.${padded}` : whole
}

/** The Owner's Rule Description, e.g. "AAPL goes below what you paid (291.40)". */
export function describeRule(
  symbol: string,
  rule: Rule,
  decimals: number
): string {
  if (rule.kind === "price") {
    const threshold = formatDecimal(rule.threshold, decimals)
    return rule.source === "price_paid"
      ? `${symbol} goes ${rule.direction} what you paid (${threshold})`
      : `${symbol} goes ${rule.direction} ${threshold}`
  }
  return `${symbol} ${rule.direction} ${normaliseDecimal(rule.percent)}% from today's open`
}

/** The public Rule Description; null for a Private Rule, which has none. */
export function describePublicRule(
  symbol: string,
  rule: Rule,
  decimals: number
): string | null {
  if (rule.kind === "price" && rule.source === "price_paid") {
    return null
  }
  return describeRule(symbol, rule, decimals)
}

const ALERT_ID = /^a-[A-Za-z0-9_-]{22}$/

/** A new Alert id: "a-" followed by 128 random bits, base64url. */
export function newAlertId(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16))
  const base64 = btoa(String.fromCharCode(...bytes))
  return `a-${base64.replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "")}`
}

export function isAlertId(value: string): boolean {
  return ALERT_ID.test(value)
}

import type { DatabaseSync } from "node:sqlite"

import {
  type AlertFieldErrors,
  type AlertInput,
  alertSchemaFor,
  decimalFromNumber,
  describePublicRule,
  describeRule,
  isAlertId,
  normaliseDecimal,
  type PercentDirection,
  type PriceDirection,
  type Rule,
  type RuleInput,
  toFieldErrors,
} from "@/lib/alert-rules"
import { getInstrumentBySymbol } from "./instruments"

// The alerts domain module: every rule about creating, changing, pausing,
// resuming and deleting an Alert, its outbox, and its public projection.
// Callers pass the Owner explicitly; the server functions take it from the session.

export type HoldingsLookup = (
  personId: string,
  symbol: string
) => { pricePaid: number } | null

export interface AlertsDeps {
  db: DatabaseSync
  holdings: HoldingsLookup
  now: () => Date
}

export interface MatchView {
  matchedAt: string
  price: string
}

export interface Alert {
  id: string
  symbol: string
  instrumentName: string
  decimals: number
  title: string | null
  state: "active" | "paused"
  rule: Rule
  /** The Owner's Rule Description. */
  description: string
  ruleRevision: number
  version: number
  createdAt: string
  updatedAt: string
  /** The latest Match of the current Rule Revision. Always null until Ingest exists. */
  latestMatch: MatchView | null
}

export type AlertError =
  | { code: "not_found" }
  | { code: "id_unavailable" }
  | { code: "stale_version"; latest: Alert }
  | { code: "invalid"; fieldErrors: AlertFieldErrors }
  | { code: "holding_missing"; symbol: string }

export type AlertResult =
  | { ok: true; alert: Alert }
  | { ok: false; error: AlertError }

export interface AlertEdit {
  title: string
  rule: AlertInput["rule"]
}

/** What a Shared Link may show. Built from public columns only (design §8). */
export interface PublicAlert {
  symbol: string
  instrumentName: string
  description: string
  state: "active" | "paused"
  latestMatch: MatchView | null
  /** The Instrument's Checked-through; null until Ingest exists. */
  checkedThrough: string | null
}

/** The rule message of design §5, as written to the outbox. */
export interface RuleMessage {
  alert_id: string
  version: number
  rule_revision: number
  person_id: string
  symbol: string
  state: "active" | "paused" | "deleted"
  rule:
    | { kind: "price"; direction: PriceDirection; threshold: string }
    | {
        kind: "percentage"
        direction: PercentDirection
        percent: string
        baseline: "todays_open"
      }
    | null
}

export interface Alerts {
  create(ownerId: string, id: string, input: AlertInput): AlertResult
  update(
    ownerId: string,
    id: string,
    expectedVersion: number,
    edit: AlertEdit
  ): AlertResult
  pause(ownerId: string, id: string): AlertResult
  resume(ownerId: string, id: string): AlertResult
  delete(
    ownerId: string,
    id: string
  ): { ok: true } | { ok: false; error: { code: "not_found" } }
  list(ownerId: string): Alert[]
  get(ownerId: string, id: string): Alert | null
  publicView(id: string): PublicAlert | null
  /** The outbox, oldest first: what the future Rule Relay will publish. */
  pendingRuleMessages(): RuleMessage[]
}

const SCHEMA = `
  CREATE TABLE IF NOT EXISTS alerts (
    id TEXT PRIMARY KEY,
    owner_id TEXT NOT NULL,
    symbol TEXT NOT NULL,
    title TEXT,
    state TEXT NOT NULL CHECK (state IN ('active', 'paused', 'deleted')),
    rule_kind TEXT,
    direction TEXT,
    threshold_source TEXT,
    threshold TEXT,
    percent TEXT,
    rule_revision INTEGER NOT NULL,
    version INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS alerts_by_owner ON alerts (owner_id, created_at);

  CREATE TABLE IF NOT EXISTS matches (
    event_id TEXT PRIMARY KEY,
    alert_id TEXT NOT NULL,
    rule_revision INTEGER NOT NULL,
    matched_at TEXT NOT NULL,
    price TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS matches_by_alert
    ON matches (alert_id, rule_revision, matched_at DESC, event_id DESC);

  CREATE TABLE IF NOT EXISTS alert_pauses (
    id INTEGER PRIMARY KEY,
    alert_id TEXT NOT NULL,
    rule_revision INTEGER NOT NULL,
    paused_at TEXT NOT NULL,
    resumed_at TEXT
  );
  CREATE INDEX IF NOT EXISTS alert_pauses_by_alert ON alert_pauses (alert_id);

  CREATE TABLE IF NOT EXISTS rule_outbox (
    seq INTEGER PRIMARY KEY AUTOINCREMENT,
    alert_id TEXT NOT NULL,
    version INTEGER NOT NULL,
    message TEXT NOT NULL,
    created_at TEXT NOT NULL
  );
`

interface AlertRow {
  id: string
  owner_id: string
  symbol: string
  title: string | null
  state: "active" | "paused" | "deleted"
  rule_kind: "price" | "percentage" | null
  direction: string | null
  threshold_source: "typed" | "price_paid" | null
  threshold: string | null
  percent: string | null
  rule_revision: number
  version: number
  created_at: string
  updated_at: string
  latest_matched_at: string | null
  latest_price: string | null
}

// Every read of an Alert goes through this: the latest Match is always of the
// current Rule Revision, so a Match of an old Rule is never shown.
const SELECT_ALERT = `
  SELECT a.*, m.matched_at AS latest_matched_at, m.price AS latest_price
  FROM alerts a
  LEFT JOIN matches m ON m.event_id = (
    SELECT event_id FROM matches
    WHERE alert_id = a.id AND rule_revision = a.rule_revision
    ORDER BY matched_at DESC, event_id DESC
    LIMIT 1
  )
`

// The public projection (design §8): an explicit list of public columns — never
// the Alert Title, the Owner, or anything from a Holding — and Private Rules
// refused in the query itself, behind the form that never offers sharing them.
const SELECT_PUBLIC_ALERT = `
  SELECT a.symbol, a.state, a.rule_kind, a.direction, a.threshold_source,
    a.threshold, a.percent,
    m.matched_at AS latest_matched_at, m.price AS latest_price
  FROM alerts a
  LEFT JOIN matches m ON m.event_id = (
    SELECT event_id FROM matches
    WHERE alert_id = a.id AND rule_revision = a.rule_revision
    ORDER BY matched_at DESC, event_id DESC
    LIMIT 1
  )
  WHERE a.id = ?
    AND a.state IN ('active', 'paused')
    AND a.threshold_source IS NOT 'price_paid'
`

type PublicAlertRow = Pick<
  AlertRow,
  | "symbol"
  | "state"
  | "rule_kind"
  | "direction"
  | "threshold_source"
  | "threshold"
  | "percent"
  | "latest_matched_at"
  | "latest_price"
>

function toPublicAlert(row: PublicAlertRow): PublicAlert | null {
  const instrument = getInstrumentBySymbol(row.symbol)
  const description = describePublicRule(
    row.symbol,
    ruleOf(row),
    instrument?.decimals ?? 2
  )
  if (!instrument || !description) {
    return null
  }
  return {
    symbol: row.symbol,
    instrumentName: instrument.name,
    description,
    state: row.state as "active" | "paused",
    latestMatch:
      row.latest_matched_at && row.latest_price
        ? { matchedAt: row.latest_matched_at, price: row.latest_price }
        : null,
    checkedThrough: null,
  }
}

function ruleOf(
  row: Pick<
    AlertRow,
    "rule_kind" | "direction" | "threshold_source" | "threshold" | "percent"
  >
): Rule {
  if (row.rule_kind === "price") {
    return {
      kind: "price",
      direction: row.direction as PriceDirection,
      source: row.threshold_source as "typed" | "price_paid",
      threshold: row.threshold as string,
    }
  }
  return {
    kind: "percentage",
    direction: row.direction as PercentDirection,
    percent: row.percent as string,
  }
}

function toAlert(row: AlertRow): Alert {
  const instrument = getInstrumentBySymbol(row.symbol)
  const decimals = instrument?.decimals ?? 2
  const rule = ruleOf(row)
  return {
    id: row.id,
    symbol: row.symbol,
    instrumentName: instrument?.name ?? row.symbol,
    decimals,
    title: row.title,
    state: row.state as "active" | "paused",
    rule,
    description: describeRule(row.symbol, rule, decimals),
    ruleRevision: row.rule_revision,
    version: row.version,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    latestMatch:
      row.latest_matched_at && row.latest_price
        ? { matchedAt: row.latest_matched_at, price: row.latest_price }
        : null,
  }
}

function ruleMessageOf(row: AlertRow): RuleMessage {
  const base = {
    alert_id: row.id,
    version: row.version,
    rule_revision: row.rule_revision,
    person_id: row.owner_id,
    symbol: row.symbol,
  }
  if (row.state === "deleted") {
    return { ...base, state: "deleted", rule: null }
  }
  const rule = ruleOf(row)
  return {
    ...base,
    state: row.state,
    rule:
      rule.kind === "price"
        ? {
            kind: "price",
            direction: rule.direction,
            threshold: rule.threshold,
          }
        : {
            kind: "percentage",
            direction: rule.direction,
            percent: rule.percent,
            baseline: "todays_open",
          },
  }
}

function ruleColumns(rule: Rule) {
  return {
    rule_kind: rule.kind,
    direction: rule.direction,
    threshold_source: rule.kind === "price" ? rule.source : null,
    threshold: rule.kind === "price" ? rule.threshold : null,
    percent: rule.kind === "percentage" ? rule.percent : null,
  }
}

/** Both Rules are already normalised, so "5" and "5.00" compare equal. */
function sameRule(a: Rule, b: Rule): boolean {
  const left = ruleColumns(a)
  const right = ruleColumns(b)
  return (Object.keys(left) as (keyof typeof left)[]).every(
    (column) => left[column] === right[column]
  )
}

const NOT_FOUND = { ok: false, error: { code: "not_found" } } as const

function invalid(fieldErrors: AlertFieldErrors): AlertResult {
  return { ok: false, error: { code: "invalid", fieldErrors } }
}

/** Checks the input against its Instrument; the Instrument's limits come from the catalogue. */
function validate(input: AlertInput): AlertFieldErrors | null {
  const instrument = getInstrumentBySymbol(input.symbol)
  if (!instrument) {
    return { symbol: "Choose an instrument" }
  }
  const parsed = alertSchemaFor(instrument.decimals).safeParse(input)
  return parsed.success ? null : toFieldErrors(parsed.error)
}

export function createAlerts({ db, holdings, now }: AlertsDeps): Alerts {
  db.exec(SCHEMA)

  /** The Rule with its threshold resolved; null when a Private Rule has no Holding behind it. */
  function resolveRule(
    ownerId: string,
    symbol: string,
    input: RuleInput
  ): Rule | null {
    if (input.kind === "percentage") {
      return {
        kind: "percentage",
        direction: input.direction,
        percent: normaliseDecimal(input.percent),
      }
    }
    if (input.threshold.source === "typed") {
      return {
        kind: "price",
        direction: input.direction,
        source: "typed",
        threshold: normaliseDecimal(input.threshold.price),
      }
    }
    const holding = holdings(ownerId, symbol)
    return holding
      ? {
          kind: "price",
          direction: input.direction,
          source: "price_paid",
          threshold: normaliseDecimal(decimalFromNumber(holding.pricePaid)),
        }
      : null
  }

  const selectById = db.prepare(`${SELECT_ALERT} WHERE a.id = ?`)
  const selectOwned = db.prepare(
    `${SELECT_ALERT} WHERE a.id = ? AND a.owner_id = ? AND a.state != 'deleted'`
  )
  const selectPublic = db.prepare(SELECT_PUBLIC_ALERT)
  const selectOwnerAlerts = db.prepare(
    `${SELECT_ALERT} WHERE a.owner_id = ? AND a.state != 'deleted' ORDER BY a.created_at DESC, a.id`
  )
  const insertAlert = db.prepare(`
    INSERT INTO alerts (id, owner_id, symbol, title, state, rule_kind, direction,
      threshold_source, threshold, percent, rule_revision, version, created_at, updated_at)
    VALUES (:id, :owner_id, :symbol, :title, :state, :rule_kind, :direction,
      :threshold_source, :threshold, :percent, :rule_revision, :version, :created_at, :updated_at)
  `)
  const updateAlert = db.prepare(`
    UPDATE alerts SET title = :title, state = :state, rule_kind = :rule_kind,
      direction = :direction, threshold_source = :threshold_source,
      threshold = :threshold, percent = :percent, rule_revision = :rule_revision,
      version = :version, updated_at = :updated_at
    WHERE id = :id
  `)
  const deleteMatches = db.prepare("DELETE FROM matches WHERE alert_id = ?")
  const deletePauses = db.prepare("DELETE FROM alert_pauses WHERE alert_id = ?")
  const openPause = db.prepare(
    "INSERT INTO alert_pauses (alert_id, rule_revision, paused_at) VALUES (?, ?, ?)"
  )
  const closePause = db.prepare(
    "UPDATE alert_pauses SET resumed_at = ? WHERE alert_id = ? AND resumed_at IS NULL"
  )
  const insertOutbox = db.prepare(
    "INSERT INTO rule_outbox (alert_id, version, message, created_at) VALUES (?, ?, ?, ?)"
  )
  const selectOutbox = db.prepare(
    "SELECT message FROM rule_outbox ORDER BY seq"
  )

  function transaction<T>(work: () => T): T {
    db.exec("BEGIN IMMEDIATE")
    try {
      const result = work()
      db.exec("COMMIT")
      return result
    } catch (error) {
      db.exec("ROLLBACK")
      throw error
    }
  }

  function rowById(id: string): AlertRow | undefined {
    return selectById.get(id) as AlertRow | undefined
  }

  function ownedRow(ownerId: string, id: string): AlertRow | undefined {
    return selectOwned.get(id, ownerId) as AlertRow | undefined
  }

  /**
   * Writes the Alert's new state. A new Rule Revision starts its Match history
   * over; pause intervals are kept per Rule Revision so a Match After Pause can
   * be worked out when reading (design §6).
   */
  function save(row: AlertRow, changes: Partial<AlertRow>): AlertRow {
    const next = {
      ...row,
      ...changes,
      version: row.version + 1,
      updated_at: now().toISOString(),
    }
    const newRevision = next.rule_revision !== row.rule_revision
    if (newRevision) {
      deleteMatches.run(row.id)
      deletePauses.run(row.id)
    }
    if (next.state === "paused" && (row.state !== "paused" || newRevision)) {
      openPause.run(row.id, next.rule_revision, next.updated_at)
    }
    if (next.state === "active" && row.state === "paused") {
      closePause.run(next.updated_at, row.id)
    }
    updateAlert.run({
      id: next.id,
      title: next.title,
      state: next.state,
      rule_kind: next.rule_kind,
      direction: next.direction,
      threshold_source: next.threshold_source,
      threshold: next.threshold,
      percent: next.percent,
      rule_revision: next.rule_revision,
      version: next.version,
      updated_at: next.updated_at,
    })
    return rowById(row.id) as AlertRow
  }

  function publish(row: AlertRow): void {
    insertOutbox.run(
      row.id,
      row.version,
      JSON.stringify(ruleMessageOf(row)),
      now().toISOString()
    )
  }

  return {
    create(ownerId, id, input) {
      if (!isAlertId(id)) {
        return { ok: false, error: { code: "id_unavailable" } }
      }
      return transaction(() => {
        // A retry of a create returns what the first attempt made; an id that is
        // someone else's, or a deleted Alert's, is refused without saying which.
        const existing = rowById(id)
        if (existing) {
          return existing.owner_id === ownerId && existing.state !== "deleted"
            ? { ok: true, alert: toAlert(existing) }
            : { ok: false, error: { code: "id_unavailable" } }
        }
        const fieldErrors = validate(input)
        if (fieldErrors) {
          return invalid(fieldErrors)
        }
        const rule = resolveRule(ownerId, input.symbol, input.rule)
        if (!rule) {
          return {
            ok: false,
            error: { code: "holding_missing", symbol: input.symbol },
          }
        }
        const timestamp = now().toISOString()
        insertAlert.run({
          id,
          owner_id: ownerId,
          symbol: input.symbol,
          title: input.title.trim() || null,
          state: "active",
          ...ruleColumns(rule),
          rule_revision: 1,
          version: 1,
          created_at: timestamp,
          updated_at: timestamp,
        })
        const row = rowById(id) as AlertRow
        publish(row)
        return { ok: true, alert: toAlert(row) }
      })
    },
    update(ownerId, id, expectedVersion, edit) {
      return transaction((): AlertResult => {
        const row = ownedRow(ownerId, id)
        if (!row) {
          return NOT_FOUND
        }
        if (row.version !== expectedVersion) {
          return {
            ok: false,
            error: { code: "stale_version", latest: toAlert(row) },
          }
        }
        const fieldErrors = validate({ symbol: row.symbol, ...edit })
        if (fieldErrors) {
          return invalid(fieldErrors)
        }
        const rule = resolveRule(ownerId, row.symbol, edit.rule)
        if (!rule) {
          return {
            ok: false,
            error: { code: "holding_missing", symbol: row.symbol },
          }
        }
        const title = edit.title.trim() || null
        const ruleChanged = !sameRule(ruleOf(row), rule)
        if (!ruleChanged && title === row.title) {
          return { ok: true, alert: toAlert(row) }
        }
        const saved = save(
          row,
          ruleChanged
            ? {
                title,
                ...ruleColumns(rule),
                rule_revision: row.rule_revision + 1,
              }
            : { title }
        )
        if (ruleChanged) {
          publish(saved)
        }
        return { ok: true, alert: toAlert(saved) }
      })
    },
    pause(ownerId, id) {
      return transaction((): AlertResult => {
        const row = ownedRow(ownerId, id)
        if (!row) {
          return NOT_FOUND
        }
        if (row.state === "paused") {
          return { ok: true, alert: toAlert(row) }
        }
        const saved = save(row, { state: "paused" })
        publish(saved)
        return { ok: true, alert: toAlert(saved) }
      })
    },
    resume(ownerId, id) {
      return transaction((): AlertResult => {
        const row = ownedRow(ownerId, id)
        if (!row) {
          return NOT_FOUND
        }
        if (row.state === "active") {
          return { ok: true, alert: toAlert(row) }
        }
        // A Private Rule follows its Holding: check it still exists and use
        // today's Price Paid, as a new Rule Revision if it changed.
        const current = ruleOf(row)
        let changes: Partial<AlertRow> = { state: "active" }
        if (current.kind === "price" && current.source === "price_paid") {
          const rule = resolveRule(ownerId, row.symbol, {
            kind: "price",
            direction: current.direction,
            threshold: { source: "price_paid" },
          })
          if (!rule) {
            return {
              ok: false,
              error: { code: "holding_missing", symbol: row.symbol },
            }
          }
          if (!sameRule(current, rule)) {
            changes = {
              ...changes,
              ...ruleColumns(rule),
              rule_revision: row.rule_revision + 1,
            }
          }
        }
        const saved = save(row, changes)
        publish(saved)
        return { ok: true, alert: toAlert(saved) }
      })
    },
    delete(ownerId, id) {
      return transaction(() => {
        const row = ownedRow(ownerId, id)
        if (!row) {
          return NOT_FOUND
        }
        // A tombstone: the id stays taken, so a late retry of its create
        // cannot bring it back; everything the Owner wrote is cleared.
        deleteMatches.run(id)
        deletePauses.run(id)
        const tombstone = save(row, {
          state: "deleted",
          title: null,
          rule_kind: null,
          direction: null,
          threshold_source: null,
          threshold: null,
          percent: null,
        })
        publish(tombstone)
        return { ok: true } as const
      })
    },
    list(ownerId) {
      return (selectOwnerAlerts.all(ownerId) as unknown as AlertRow[]).map(
        toAlert
      )
    },
    get(ownerId, id) {
      const row = selectOwned.get(id, ownerId) as AlertRow | undefined
      return row ? toAlert(row) : null
    },
    publicView(id) {
      const row = selectPublic.get(id) as PublicAlertRow | undefined
      return row ? toPublicAlert(row) : null
    },
    pendingRuleMessages() {
      return (selectOutbox.all() as { message: string }[]).map(
        (row) => JSON.parse(row.message) as RuleMessage
      )
    },
  }
}

import { type FormEvent, type ReactNode, useId, useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select"
import {
  type AlertFieldErrors,
  type AlertInput,
  alertSchemaFor,
  describeRule,
  formatDecimal,
  type PercentDirection,
  type PriceDirection,
  type Rule,
  toFieldErrors,
} from "@/lib/alert-rules"
import { formatPrice } from "@/lib/format-price"
import type { Alert } from "@/server/alerts"
import type { AlertFormContext } from "@/server/functions"

export interface AlertFormValues {
  symbol: string
  kind: "price" | "percentage"
  priceDirection: PriceDirection
  percentDirection: PercentDirection
  source: "typed" | "price_paid"
  price: string
  percent: string
  title: string
}

/** What the page tells the form after a submit that didn't leave it. */
export interface AlertFormFeedback {
  fieldErrors?: AlertFieldErrors
  formError?: string
}

export function emptyAlertValues(symbol: string): AlertFormValues {
  return {
    symbol,
    kind: "price",
    priceDirection: "above",
    percentDirection: "rises",
    source: "typed",
    price: "",
    percent: "",
    title: "",
  }
}

export function alertValuesFrom(alert: Alert): AlertFormValues {
  const values = emptyAlertValues(alert.symbol)
  values.title = alert.title ?? ""
  const { rule } = alert
  if (rule.kind === "price") {
    values.kind = "price"
    values.priceDirection = rule.direction
    values.source = rule.source
    values.price = rule.source === "typed" ? rule.threshold : ""
  } else {
    values.kind = "percentage"
    values.percentDirection = rule.direction
    values.percent = rule.percent
  }
  return values
}

type FieldKey =
  | "symbol"
  | "title"
  | "rule.threshold.price"
  | "rule.threshold"
  | "rule.percent"

const FIELD_KEYS: readonly string[] = [
  "symbol",
  "title",
  "rule.threshold.price",
  "rule.threshold",
  "rule.percent",
] satisfies FieldKey[]

type AlertFormProps = {
  context: AlertFormContext
  initialValues: AlertFormValues
  /** Edit mode: the Instrument can't change, so it is shown as text. */
  lockedSymbol?: boolean
  submitLabel: string
  onSubmit: (input: AlertInput) => Promise<AlertFormFeedback | undefined>
}

export function AlertForm({
  context,
  initialValues,
  lockedSymbol = false,
  submitLabel,
  onSubmit,
}: AlertFormProps) {
  const id = useId()
  const [values, setValues] = useState(initialValues)
  const [touched, setTouched] = useState<ReadonlySet<string>>(new Set())
  const [submitted, setSubmitted] = useState(false)
  const [serverErrors, setServerErrors] = useState<AlertFieldErrors>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [pending, setPending] = useState(false)
  const pendingRef = useRef(false)

  const instrument = context.instruments.find(
    (candidate) => candidate.symbol === values.symbol
  )
  const decimals = instrument?.decimals ?? 2
  const pricePaid = context.pricesPaid[values.symbol]
  // "What I paid" is only offered for an Instrument the Owner holds.
  const source = pricePaid ? values.source : "typed"
  const input = toInput(values, source)
  const parsed = alertSchemaFor(decimals).safeParse(input)
  const clientErrors: AlertFieldErrors = parsed.success
    ? {}
    : toFieldErrors(parsed.error)
  if (!instrument && !clientErrors.symbol) {
    clientErrors.symbol = "Choose an instrument"
  }
  const preview =
    parsed.success && instrument
      ? previewRule(parsed.data, pricePaid, decimals)
      : null

  const errorFor = (key: FieldKey): string | undefined =>
    serverErrors[key] ??
    (submitted || touched.has(key) ? clientErrors[key] : undefined)

  const otherErrors = submitted
    ? Object.entries({ ...clientErrors, ...serverErrors })
        .filter(([key]) => !FIELD_KEYS.includes(key))
        .map(([, message]) => message)
    : []

  const update = (patch: Partial<AlertFormValues>) => {
    setValues((current) => ({ ...current, ...patch }))
    setServerErrors({})
    setFormError(null)
  }
  const touch = (key: FieldKey) => {
    setTouched((current) =>
      current.has(key) ? current : new Set(current).add(key)
    )
  }

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (pendingRef.current) {
      return
    }
    setSubmitted(true)
    setServerErrors({})
    setFormError(null)
    if (!parsed.success || !instrument) {
      return
    }
    pendingRef.current = true
    setPending(true)
    try {
      const feedback = await onSubmit(input)
      if (feedback?.fieldErrors) {
        setServerErrors(feedback.fieldErrors)
      }
      if (feedback?.formError) {
        setFormError(feedback.formError)
      }
    } catch {
      setFormError("Couldn't save this alert. Please try again.")
    } finally {
      pendingRef.current = false
      setPending(false)
    }
  }

  const fieldId = (name: string) => `${id}-${name}`
  const symbolError = errorFor("symbol")
  const priceError = errorFor("rule.threshold.price")
  const thresholdError = errorFor("rule.threshold")
  const percentError = errorFor("rule.percent")
  const titleError = errorFor("title")

  return (
    <form noValidate onSubmit={(event) => void handleSubmit(event)}>
      <FieldGroup>
        {lockedSymbol ? (
          <Field>
            <p className="text-sm font-medium">Instrument</p>
            <p className="text-base">
              {instrument
                ? `${instrument.symbol} — ${instrument.name}`
                : values.symbol}
            </p>
            {instrument ? <LastPrice instrument={instrument} /> : null}
          </Field>
        ) : (
          <Field data-invalid={symbolError ? true : undefined}>
            <FieldLabel htmlFor={fieldId("symbol")}>Instrument</FieldLabel>
            <NativeSelect
              id={fieldId("symbol")}
              className="w-full max-w-md"
              value={values.symbol}
              aria-invalid={symbolError ? true : undefined}
              aria-describedby={
                symbolError ? fieldId("symbol-error") : undefined
              }
              onChange={(event) => {
                update({ symbol: event.target.value })
                touch("symbol")
              }}
              onBlur={() => touch("symbol")}
            >
              {instrument ? null : (
                <NativeSelectOption value="">
                  Choose an instrument
                </NativeSelectOption>
              )}
              {context.instruments.map((candidate) => (
                <NativeSelectOption
                  key={candidate.symbol}
                  value={candidate.symbol}
                >
                  {candidate.symbol} — {candidate.name}
                </NativeSelectOption>
              ))}
            </NativeSelect>
            {instrument ? <LastPrice instrument={instrument} /> : null}
            <FieldError id={fieldId("symbol-error")}>{symbolError}</FieldError>
          </Field>
        )}

        <ChoiceGroup
          label="Rule kind"
          name={fieldId("kind")}
          value={values.kind}
          options={[
            { value: "price", label: "Price" },
            { value: "percentage", label: "Percentage" },
          ]}
          onChange={(kind) => update({ kind })}
        />

        {values.kind === "price" ? (
          <>
            <ChoiceGroup
              label="Direction"
              name={fieldId("price-direction")}
              value={values.priceDirection}
              options={[
                { value: "above", label: "Goes above" },
                { value: "below", label: "Goes below" },
              ]}
              onChange={(priceDirection) => update({ priceDirection })}
            />
            <ChoiceGroup
              label="Threshold"
              name={fieldId("source")}
              value={source}
              options={[
                { value: "typed", label: "A price" },
                ...(pricePaid
                  ? [
                      {
                        value: "price_paid" as const,
                        label: `What I paid (${formatDecimal(pricePaid, decimals)})`,
                      },
                    ]
                  : []),
              ]}
              onChange={(nextSource) => {
                update({ source: nextSource })
                touch("rule.threshold")
              }}
              error={thresholdError}
              errorId={fieldId("threshold-error")}
            />
            {source === "typed" ? (
              <Field data-invalid={priceError ? true : undefined}>
                <FieldLabel htmlFor={fieldId("price")}>Price</FieldLabel>
                <Input
                  id={fieldId("price")}
                  className="max-w-xs"
                  inputMode="decimal"
                  autoComplete="off"
                  value={values.price}
                  aria-invalid={priceError ? true : undefined}
                  aria-describedby={
                    priceError ? fieldId("price-error") : undefined
                  }
                  onChange={(event) => update({ price: event.target.value })}
                  onBlur={() => touch("rule.threshold.price")}
                />
                <FieldError id={fieldId("price-error")}>
                  {priceError}
                </FieldError>
              </Field>
            ) : null}
          </>
        ) : (
          <>
            <ChoiceGroup
              label="Direction"
              name={fieldId("percent-direction")}
              value={values.percentDirection}
              options={[
                { value: "rises", label: "Rises by" },
                { value: "falls", label: "Falls by" },
              ]}
              onChange={(percentDirection) => update({ percentDirection })}
            />
            <Field data-invalid={percentError ? true : undefined}>
              <FieldLabel htmlFor={fieldId("percent")}>Percent</FieldLabel>
              <div className="flex items-center gap-2">
                <Input
                  id={fieldId("percent")}
                  className="max-w-32"
                  inputMode="decimal"
                  autoComplete="off"
                  value={values.percent}
                  aria-invalid={percentError ? true : undefined}
                  aria-describedby={
                    percentError
                      ? `${fieldId("percent-suffix")} ${fieldId("percent-error")}`
                      : fieldId("percent-suffix")
                  }
                  onChange={(event) => update({ percent: event.target.value })}
                  onBlur={() => touch("rule.percent")}
                />
                <span
                  id={fieldId("percent-suffix")}
                  className="text-sm text-muted-foreground"
                >
                  % from today's open
                </span>
              </div>
              <FieldError id={fieldId("percent-error")}>
                {percentError}
              </FieldError>
            </Field>
          </>
        )}

        <Field data-invalid={titleError ? true : undefined}>
          <FieldLabel htmlFor={fieldId("title")}>
            Alert title (optional)
          </FieldLabel>
          <Input
            id={fieldId("title")}
            className="max-w-md"
            autoComplete="off"
            value={values.title}
            aria-invalid={titleError ? true : undefined}
            aria-describedby={
              titleError
                ? `${fieldId("title-hint")} ${fieldId("title-error")}`
                : fieldId("title-hint")
            }
            onChange={(event) => update({ title: event.target.value })}
            onBlur={() => touch("title")}
          />
          <FieldDescription id={fieldId("title-hint")}>
            Only you see this. It helps you find this alert later.
          </FieldDescription>
          <FieldError id={fieldId("title-error")}>{titleError}</FieldError>
        </Field>

        <div aria-live="polite" className="min-h-6">
          {preview ? (
            <p className="rounded-2xl bg-muted px-4 py-3 text-sm">
              <span className="text-muted-foreground">Rule: </span>
              <span className="font-medium">{preview}</span>
            </p>
          ) : null}
        </div>

        {formError || otherErrors.length > 0 ? (
          <div role="alert" className="text-sm text-destructive">
            {formError ? <p>{formError}</p> : null}
            {otherErrors.map((message) => (
              <p key={message}>{message}</p>
            ))}
          </div>
        ) : null}

        <div>
          <Button type="submit" disabled={pending}>
            {submitLabel}
          </Button>
        </div>
      </FieldGroup>
    </form>
  )
}

function LastPrice({
  instrument,
}: {
  instrument: AlertFormContext["instruments"][number]
}) {
  return (
    <p className="text-sm text-muted-foreground tabular-nums">
      Last price {formatPrice(instrument.last_price, instrument.decimals)}
    </p>
  )
}

type ChoiceGroupProps<T extends string> = {
  label: string
  name: string
  value: T
  options: { value: T; label: ReactNode }[]
  onChange: (value: T) => void
  error?: string
  errorId?: string
}

/** A labelled radio group of native radios, so its roles and names are the platform's. */
function ChoiceGroup<T extends string>({
  label,
  name,
  value,
  options,
  onChange,
  error,
  errorId,
}: ChoiceGroupProps<T>) {
  const labelId = `${name}-label`
  return (
    <div
      role="radiogroup"
      aria-labelledby={labelId}
      aria-invalid={error ? true : undefined}
      aria-describedby={error ? errorId : undefined}
      className="flex flex-col gap-2"
    >
      <span id={labelId} className="text-sm font-medium">
        {label}
      </span>
      <div className="flex flex-wrap gap-x-6 gap-y-2">
        {options.map((option) => (
          <label
            key={option.value}
            className="flex cursor-pointer items-center gap-2 text-sm"
          >
            <input
              type="radio"
              name={name}
              value={option.value}
              checked={value === option.value}
              onChange={() => onChange(option.value)}
              className="size-4 accent-primary"
            />
            {option.label}
          </label>
        ))}
      </div>
      <FieldError id={errorId}>{error}</FieldError>
    </div>
  )
}

function toInput(
  values: AlertFormValues,
  source: AlertFormValues["source"]
): AlertInput {
  return {
    symbol: values.symbol,
    title: values.title,
    rule:
      values.kind === "price"
        ? {
            kind: "price",
            direction: values.priceDirection,
            threshold:
              source === "typed"
                ? { source: "typed", price: values.price }
                : { source: "price_paid" },
          }
        : {
            kind: "percentage",
            direction: values.percentDirection,
            percent: values.percent,
          },
  }
}

/** The Owner's Rule Description of what the form holds right now. */
function previewRule(
  input: AlertInput,
  pricePaid: string | undefined,
  decimals: number
): string | null {
  const { rule } = input
  let resolved: Rule
  if (rule.kind === "percentage") {
    resolved = rule
  } else if (rule.threshold.source === "typed") {
    resolved = {
      kind: "price",
      direction: rule.direction,
      source: "typed",
      threshold: rule.threshold.price,
    }
  } else if (pricePaid) {
    resolved = {
      kind: "price",
      direction: rule.direction,
      source: "price_paid",
      threshold: pricePaid,
    }
  } else {
    return null
  }
  return describeRule(input.symbol, resolved, decimals)
}

