})

describe("rule messages", () => {
  it("never carry the Alert Title, and each Alert's version only increases", () => {
    const { alerts } = setup()
    const title = "bought 25 @ 280.00"
    const first = created(
      alerts.create(AVA, alertId(), { ...priceBelow("300"), title })
    )
    const second = created(
